//! The carried `small_dungeon` pools, processor chains and structure definition.
//!
//! Generated by `tools/gen_tables.py` from the jar; do not edit. These are the jar's
//! own weights, order and limits in a form a Rust `StructureType` can run: the
//! data-pack form of the pools is what the engine refuses to decode
//! (`yungsapi:yung_single_element` and the mod's own `betterdungeons:*` processor
//! types).

/// One weighted pool element.
#[derive(Clone, Copy, Debug)]
pub struct Element {
    /// Its weight in the pool.
    pub weight: i32,
    /// The template it places.
    pub template: &'static str,
    /// The processor list it runs, `minecraft:empty` for none.
    pub processors: &'static str,
    /// Its `name`, which a parent's `target` must equal; `max_count` needs it.
    pub name: Option<&'static str>,
    /// Its `max_count` in the whole structure, when limited.
    pub max_count: Option<i32>,
}

/// One template pool.
#[derive(Clone, Copy, Debug)]
pub struct Pool {
    /// Its id.
    pub id: &'static str,
    /// The pool drawn when this one yields nothing.
    pub fallback: &'static str,
    /// Its elements, in the jar's file order (a draw shuffles a copy).
    pub elements: &'static [Element],
}

