/// The pool `id` names, or `None`.
pub fn pool(id: &str) -> Option<&'static Pool> {
    POOLS.iter().find(|pool| pool.id == id)
}

/// One `minecraft:rule` processor's rule.
#[derive(Clone, Copy, Debug)]
pub struct Rule {
    /// The state it matches.
    pub input: u16,
    /// The state it writes.
    pub output: u16,
    /// Its chance; 1.0 for `block_match`.
    pub probability: f32,
}

/// One processor in a chain, in the jar's order.
#[derive(Clone, Copy, Debug)]
pub struct Step {
    /// A `KIND_*` value naming the processor.
    pub kind: u8,
    /// Its parameter: the dungeon type, or the spawner's mob id.
    pub text: &'static str,
    /// Its rules, for `KIND_RULE`.
    pub rules: &'static [Rule],
}

/// One processor list.
#[derive(Clone, Copy, Debug)]
pub struct ProcList {
    /// Its id.
    pub id: &'static str,
    /// Its processors, in the jar's order.
    pub steps: &'static [Step],
}

