/// The structure definition as the jar carries it. `/betterdungeons status` reports
/// it, and `find_generation_point` compares a pack's own config against it.
#[derive(Clone, Copy, Debug)]
pub struct StructureDef {
    /// Its id.
    pub id: &'static str,
    /// The jar's `type` (`yungsapi:yung_jigsaw`).
    pub worldgen_type: &'static str,
    /// Its `start_pool`.
    pub start_pool: &'static str,
    /// Its `start_jigsaw_name`.
    pub start_jigsaw: Option<&'static str>,
    /// Its `size`, the jigsaw depth cap.
    pub size: i32,
    /// Its `start_height` as an inclusive absolute range.
    pub start_y: (i32, i32),
    /// Its `max_distance_from_center`.
    pub max_distance: i32,
    /// Its `use_expansion_hack`.
    pub use_expansion_hack: bool,
    /// Its `step`.
    pub step: &'static str,
    /// Its `biomes` tag.
    pub biomes: &'static str,
    /// Its `liquid_settings`.
    pub liquid_settings: &'static str,
    /// Its structure set's `salt`.
    pub salt: i32,
    /// Its structure set's `spacing`, in chunks.
    pub spacing: i32,
    /// Its structure set's `separation`, in chunks.
    pub separation: i32,
}

